fn power(base, exp):
    result = 1;
    for i in range(exp):
        result = result * base;
    close
    ret result;
close

fn compound_interest(p, r, n):
    rate = 1.0 + r / 100.0;
    factor = power(rate, n);
    amount = p * factor;
    ret amount;
close

