show '\n';

fn is_armstrong(n):
    d1 = n // 100;
    d2 = (n // 10) % 10;
    d3 = n % 10;
    sum_cubes = d1 ** 3 + d2 ** 3 + d3 ** 3;
    ret sum_cubes == n;
close

